  suite: { maxNights: 21, minNights: 1, maxGuests: 4, baseRate: 150, highSurcharge: 60, flatFee: 0, thirdGuestFee: 25 },
  villa: { maxNights: 28, minNights: 3, maxGuests: 8, baseRate: 300, highSurcharge: 120, flatFee: 500, thirdGuestFee: 0 },
};

export function quoteBooking(raw: unknown): QuoteResult {
