(!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
   return { ok: false, error: "bad loyalty" };
 }
 const rule = RULES[req.category as Category];
 if (!rule) {
   return { ok: false, error: "unknown category" };
 }

